-- Changelog: acties met een doorloop krijgen één herkenbare startknop.
insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-01','verbeterd','Acties','Duidelijke startknop bij acties op je telefoon',
   'Bij een actie waar je een formulier moet invullen, een kwaliteitsronde moet lopen of een toolbox moet doorlopen staat nu een grote groene knop die je meteen naar het juiste scherm brengt. Zulke acties hebben geen los vinkje meer: ze gaan vanzelf op gereed zodra je het formulier hebt ingediend, de ronde hebt afgerond of de toolbox hebt doorlopen. Zo kan een actie niet meer per ongeluk worden afgevinkt zonder dat het werk is vastgelegd.');
